package com.muxigame.city;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsHeadLoss {
 static void loseHeadDuringMeal(GameTestHelper h,CityTestsScale.Fixture f,boolean first){CityTestsModel.configure(f);var head=f.r.state.people.get(f.t.head(f.village.id).worker);var family=f.r.state.families.get(head.family);for(var p:RuralRules.members(family,f.r.state.people)){p.nourishment=2;p.workingTicks=0;p.cookingCredit=0;}for(var home:f.r.state.families.values())if(home.city.equals(f.village.id)){var stores=f.r.stocks(home.id);int ready=RuralRules.take(stores,true,RuralRules.count(stores,true));h.assertTrue(RuralRules.put(stores,false,ready)==ready,"The starvation fixture swaps all rural ready bread to equal-count raw wheat without deleting grain");}if(first){var copy=new java.util.LinkedHashMap<>(f.r.state.families);f.r.state.families.clear();f.r.state.families.put(family.id,family);copy.forEach((id,value)->{if(!id.equals(family.id))f.r.state.families.put(id,value);});}head.workingTicks=1200;long cash=f.t.money(f.s),grain=f.t.grain(f.s);f.r.cycle(f.s,f.village,true,false);h.assertTrue(head.dead&&RuralRules.members(family,f.r.state.people).isEmpty(),"Both already-starving adults die in the ordinary meal settlement; they are not healed or resurrected");h.assertTrue(f.t.money(f.s)==cash&&f.t.grain(f.s)==grain,"The skipped dead-head export cannot erase currency or raw grain held by the estate");}
 @GameTest(template="empty") public static void headDeathInSameMealCannotCrashStaleMerchantList(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){loseHeadDuringMeal(h,f,false);}h.succeed();}
 @GameTest(template="empty",timeoutTicks=200) public static void settlementKeepsAuditingSixtyDaysAfterHeadDeath(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){loseHeadDuringMeal(h,f,true);f.run(60);h.assertTrue(f.conserved,"A headless village can continue its existing production and meals without a server exception, resurrection, new head assets or money/food accounting errors");}h.succeed();}
 @GameTest(template="empty") public static void deadHeadPrivateReserveIsNotQuotedAsAvailableMarketFood(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var head=f.r.state.people.get(f.t.head(f.village.id).worker);long grain=f.t.grain(f.s);head.dead=true;h.assertTrue(f.t.liveHead(f.s,f.village.id)==null&&f.t.stock(f.s,f.village.id,0)==0&&f.t.grain(f.s)==grain,"The dead head's private food remains an estate asset, but is not falsely offered for sale or inherited by a replacement");}h.succeed();}
 @GameTest(template="empty") public static void lostCounterpartyCannotFreezeOutboundOrReturningCargo(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var head=f.r.state.people.get(f.t.head(f.village.id).worker);head.dead=true;var merchant=f.t.state.businesses.values().stream().filter(b->b.kind.equals("procurement")).findFirst().orElseThrow();merchant.cargo[0].add(3,900);merchant.cargo[0].freshness.groups.getFirst().age=FoodAge.SCALE/2;merchant.meatCargo[0].add(2,2000);merchant.phase=1;merchant.arrive=0;long grain=f.t.grain(f.s),meat=f.t.meat(f.s),cash=f.t.money(f.s);CityRoute.travel(f.s,merchant,0,0);h.assertTrue(merchant.phase==2&&merchant.cargo[0].count==3,"At the failed destination the merchant schedules a real return journey with the original cargo");CityRoute.travel(f.s,merchant,merchant.arrive,1);h.assertTrue(merchant.phase==0&&merchant.cargo[0].count==0&&merchant.stock[0].count==3&&merchant.meatListed[0].count==2&&merchant.stock[0].freshness.groups.getFirst().age==FoodAge.SCALE/2,"Already-returning cargo reaches home even without a live head, retaining its quantity, cost and freshness");h.assertTrue(f.t.grain(f.s)==grain&&f.t.meat(f.s)==meat&&f.t.money(f.s)==cash,"Cancelled trade cannot create cargo, coins, proceeds or a new owner");}h.succeed();}
 @GameTest(template="empty") public static void deadHeadCannotKeepSpendingEstateMoneyToBuyPawnedGoods(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var head=f.r.state.people.get(f.t.head(f.village.id).worker);head.dead=true;var buyer=f.r.state.people.values().stream().filter(p->p.role==RuralRules.Role.HUNTER).findFirst().orElseThrow();var family=f.r.state.families.get(buyer.family);for(var id:family.members)f.e.state.accounts.put(CityEconomy.person(id),0L);for(var stock:f.r.stocks(family.id)){stock.wheat=stock.bread=0;RuralMeat.clear(stock);}var box=f.r.state.boxes.values().stream().filter(b->family.id.equals(b.stock.family)).findFirst().orElseThrow();while(box.slots.size()<27)box.slots.add("");box.slots.set(5,"{count:1,id:\"minecraft:book\"}");long estate=f.e.balance(CityEconomy.person(head.id));f.t.emergencySale(f.s,family);h.assertTrue(f.e.balance(CityEconomy.person(head.id))==estate&&f.t.goodsCount(f.s,family,3)==1&&f.t.familyMoney(f.s,family)==0,"A deceased agent does not keep buying goods with an estate; goods and balances remain with their existing owners");}h.succeed();}
}
